"""Native fixed-context capsule; its table rel32 holes bind in the final BG pack."""
from pathlib import Path
from hepta.hia_agent_assembly import render_assembly
from tools.generate_hia_artifact_publication import document
from tools import generate_hia_background_optimizer_native_context_packers as original
ROOT=Path(__file__).resolve().parents[1]
CONFIG={'bridge': '', 'holes': {'policy': 232}, 'roles': ['policy'], 'export': 'hia_background_native_context', 'magic': 'HIABGCP2', 'relocations': [(1105, 'malloc'), (1116, 'free')]}
TABLE_HOLES={'queue': 351, 'ledger': 365, 'decimal': 379, 'jobs': 393, 'job_refs': 407, 'worker': 421, 'submission': 435, 'business': 449, 'execution': 463, 'account': 477, 'snapshot': 491, 'shutdown': 505, 'report': 519, 'structure_deferred': 533, 'transport_deferred': 547, 'freeze_deferred': 561, 'constructor': 575, 'options': 589, 'bridge_paths': 603, 'constructor_binding': 617, 'path_value': 631, 'path_resolve': 645, 'path_error': 659, 'path_string_codec': 673, 'posix_factory': 687, 'verifier': 701, 'json_capture': 715, 'sha256': 729, 'checked_freezer': 743, 'prepare_process': 757, 'verify_raw': 771, 'decision': 785, 'registry': 799, 'structure_compat': 824, 'transport_compat': 838, 'freeze_compat': 852, 'rank': 866, 'admission': 880, 'decision_policy': 894}
def run(fn,*args):
    old=original.CONFIG['context']
    try:
        original.CONFIG['context']=CONFIG
        return fn('context',*args)
    finally:original.CONFIG['context']=old
def source_program():return run(original.source_program)
def reference_object(flats):return run(original.reference_object,flats)
def main():
    name='background_optimizer_native_fixed_context_packer'
    d=document(source_program(),name)
    p=ROOT/'examples/hia_bootstrap'/(name+'.hepta');p.write_text(render_assembly(d))
    print(p.name,p.stat().st_size,len(d['functions']),sum(len(f['blocks'])for f in d['functions']),
          sum(len(b['ops'])for f in d['functions']for b in f['blocks']),flush=True)
if __name__=='__main__':main()
